vector<bool> sieve(int N) {
    vector<bool> isPrime(N + 1, true);
    isPrime[0] = isPrime[1] = false;
    for (int p = 2; (long long)p * p <= N; ++p)
        if (isPrime[p])
            for (int m = p * p; m <= N; m += p)
                isPrime[m] = false;
    return isPrime;
}

def sieve(N):
    is_prime = [True] * (N + 1)
    is_prime[0] = is_prime[1] = False
    p = 2
    while p * p <= N:
        if is_prime[p]:
            for m in range(p * p, N + 1, p):
                is_prime[m] = False
        p += 1
    return is_prime

class Solution {
public:
    int countPrimes(int n) {
        if (n < 3) return 0;
        vector<bool> composite(n, false);
        int count = 0;
        for (int p = 2; p < n; p++) {
            if (composite[p]) continue;
            count++;
            for (long long m = (long long)p * p; m < n; m += p) composite[m] = true;
        }
        return count;
    }
};

class Solution:
    def countPrimes(self, n: int) -> int:
        if n < 3:
            return 0
        composite = [False] * n
        count = 0
        for p in range(2, n):
            if composite[p]:
                continue
            count += 1
            for m in range(p * p, n, p):
                composite[m] = True
        return count

class Solution {
public:
    vector<int> closestPrimes(int left, int right) {
        vector<bool> comp(right + 1, false);
        for (int p = 2; (long long)p * p <= right; p++)
            if (!comp[p]) for (long long m = (long long)p * p; m <= right; m += p) comp[m] = true;
        int prev = -1, a = -1, b = -1, best = INT_MAX;
        for (int x = max(2, left); x <= right; x++) {
            if (comp[x]) continue;
            if (prev != -1 && x - prev < best) { best = x - prev; a = prev; b = x; }
            prev = x;
        }
        return {a, b};
    }
};

class Solution:
    def closestPrimes(self, left: int, right: int) -> list[int]:
        comp = [False] * (right + 1)
        p = 2
        while p * p <= right:
            if not comp[p]:
                for m in range(p * p, right + 1, p):
                    comp[m] = True
            p += 1
        prev, a, b, best = -1, -1, -1, float('inf')
        for x in range(max(2, left), right + 1):
            if comp[x]:
                continue
            if prev != -1 and x - prev < best:
                best, a, b = x - prev, prev, x
            prev = x
        return [a, b]

class Solution {
public:
    vector<int> primeFactorize(int n) {
        vector<int> spf(n + 1);
        for (int i = 2; i <= n; i++) if (!spf[i]) for (int j = i; j <= n; j += i) if (!spf[j]) spf[j] = i;
        vector<int> factors;
        while (n > 1) { factors.push_back(spf[n]); n /= spf[n]; }
        return factors;
    }
};

class Solution:
    def primeFactorize(self, n: int) -> list[int]:
        spf = [0] * (n + 1)
        for i in range(2, n + 1):
            if spf[i] == 0:
                for j in range(i, n + 1, i):
                    if spf[j] == 0:
                        spf[j] = i
        factors = []
        while n > 1:
            factors.append(spf[n])
            n //= spf[n]
        return factors

class Solution {
public:
    vector<int> distinctPrimeFactors(int N) {
        vector<int> cnt(N + 1, 0);
        for (int p = 2; p <= N; p++)
            if (cnt[p] == 0)                       // p is prime
                for (int m = p; m <= N; m += p) cnt[m]++;
        return cnt;
    }
};

class Solution:
    def distinctPrimeFactors(self, N: int) -> list[int]:
        cnt = [0] * (N + 1)
        for p in range(2, N + 1):
            if cnt[p] == 0:
                for m in range(p, N + 1, p):
                    cnt[m] += 1
        return cnt

class Solution {
public:
    int nthUglyNumber(int n) {
        vector<int> dp(n);
        dp[0] = 1; int i2 = 0, i3 = 0, i5 = 0;
        for (int i = 1; i < n; i++) {
            int n2 = dp[i2] * 2, n3 = dp[i3] * 3, n5 = dp[i5] * 5;
            int nxt = min({n2, n3, n5});
            dp[i] = nxt;
            if (nxt == n2) i2++;
            if (nxt == n3) i3++;
            if (nxt == n5) i5++;
        }
        return dp[n - 1];
    }
};
